import{at as e,it as t,n,vt as r}from"./chunks/framework.BUQROvXk.js";var i=JSON.parse(`{"title":"Class: GenerationRegion","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/GenerationRegion.md","filePath":"api/@jsprismarine/prismarine/classes/GenerationRegion.md"}`),a={name:`api/@jsprismarine/prismarine/classes/GenerationRegion.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / GenerationRegion</p><h1 id="class-generationregion" tabindex="-1">Class: GenerationRegion <a class="header-anchor" href="#class-generationregion" aria-label="Permalink to “Class: GenerationRegion”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L268" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:268</a></p><p>A rectangular chunk window of Java block states.</p><p>States are held as indices into a per-region palette, so the buffer is two bytes a block rather than one object reference. <a href="#surfacechunk">surfaceChunk</a> and <a href="#featureworld">featureWorld</a> project the two seams the generation stages read it through; the two interfaces spell <code>getBlock</code> differently, so neither is implemented on the class itself.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new GenerationRegion</strong>(<code>options</code>): <code>GenerationRegion</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L319" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:319</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="./../#generationregionoptions"><code>GenerationRegionOptions</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>GenerationRegion</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="maxy" tabindex="-1">maxY <a class="header-anchor" href="#maxy" aria-label="Permalink to “maxY”">​</a></h3><blockquote><p><code>readonly</code> <strong>maxY</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L272" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:272</a></p><p>The highest y the region holds.</p><hr><h3 id="miny" tabindex="-1">minY <a class="header-anchor" href="#miny" aria-label="Permalink to “minY”">​</a></h3><blockquote><p><code>readonly</code> <strong>minY</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L270" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:270</a></p><p>The lowest y the region holds.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="applypatch" tabindex="-1">applyPatch() <a class="header-anchor" href="#applypatch" aria-label="Permalink to “applyPatch()”">​</a></h3><blockquote><p><strong>applyPatch</strong>(<code>patch</code>, <code>options?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L811" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:811</a></p><p>Applies a feature pass&#39;s writes to this region.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="patch" tabindex="-1">patch <a class="header-anchor" href="#patch" aria-label="Permalink to “patch”">​</a></h5><p><code>RegionChunkPatch</code></p><p>The writes, this chunk&#39;s own or a neighbor&#39;s.</p><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><code>ApplyPatchOptions</code> = <code>{}</code></p><p>What to leave alone. A write, a block entity or its removal at a kept position is dropped; an entity spawn is kept, because it stands in the world rather than in a block.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="beginwritetracking" tabindex="-1">beginWriteTracking() <a class="header-anchor" href="#beginwritetracking" aria-label="Permalink to “beginWriteTracking()”">​</a></h3><blockquote><p><strong>beginWriteTracking</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L662" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:662</a></p><p>Starts collecting decoration writes so neighboring chunks can receive their share.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="biomesection" tabindex="-1">biomeSection() <a class="header-anchor" href="#biomesection" aria-label="Permalink to “biomeSection()”">​</a></h3><blockquote><p><strong>biomeSection</strong>(<code>index</code>): <code>number</code> | <code>Uint16Array</code>&lt;<code>ArrayBuffer</code>&gt; | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L529" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:529</a></p><p>One section&#39;s biome IDs, either a uniform id or its packed 16³ blocks.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="index" tabindex="-1">index <a class="header-anchor" href="#index" aria-label="Permalink to “index”">​</a></h5><p><code>number</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code> | <code>Uint16Array</code>&lt;<code>ArrayBuffer</code>&gt; | <code>undefined</code></p><hr><h3 id="blockat" tabindex="-1">blockAt() <a class="header-anchor" href="#blockat" aria-label="Permalink to “blockAt()”">​</a></h3><blockquote><p><strong>blockAt</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <a href="./../#regionblock"><code>RegionBlock</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L547" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:547</a></p><p>The palette entry at a block position, air outside the region.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#regionblock"><code>RegionBlock</code></a></p><hr><h3 id="centerblockentities" tabindex="-1">centerBlockEntities() <a class="header-anchor" href="#centerblockentities" aria-label="Permalink to “centerBlockEntities()”">​</a></h3><blockquote><p><strong>centerBlockEntities</strong>(): readonly <a href="./../#regionblockentity"><code>RegionBlockEntity</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L924" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:924</a></p><p>The block entities attached inside the center chunk, which is the chunk that is kept.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <a href="./../#regionblockentity"><code>RegionBlockEntity</code></a>[]</p><hr><h3 id="centerblockslots" tabindex="-1">centerBlockSlots() <a class="header-anchor" href="#centerblockslots" aria-label="Permalink to “centerBlockSlots()”">​</a></h3><blockquote><p><strong>centerBlockSlots</strong>(): <code>CenterBlockSlots</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L940" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:940</a></p><p>The center chunk&#39;s blocks as palette slots, for the translation pass.</p><p>A radius-0 region is already exactly the center chunk in exactly this layout, so it hands its own buffers over rather than copying them. They stay the region&#39;s, so a caller reads them and does not keep them.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>CenterBlockSlots</code></p><hr><h3 id="centerentityspawns" tabindex="-1">centerEntitySpawns() <a class="header-anchor" href="#centerentityspawns" aria-label="Permalink to “centerEntitySpawns()”">​</a></h3><blockquote><p><strong>centerEntitySpawns</strong>(): readonly <a href="./../#regionentityspawn"><code>RegionEntitySpawn</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L929" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:929</a></p><p>The entities asked for inside the center chunk, in the order the features asked.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <a href="./../#regionentityspawn"><code>RegionEntitySpawn</code></a>[]</p><hr><h3 id="copycenterfrom" tabindex="-1">copyCenterFrom() <a class="header-anchor" href="#copycenterfrom" aria-label="Permalink to “copyCenterFrom()”">​</a></h3><blockquote><p><strong>copyCenterFrom</strong>(<code>source</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L736" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:736</a></p><p>Copies another tile&#39;s center terrain and frozen surface heights into this region.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="source" tabindex="-1">source <a class="header-anchor" href="#source" aria-label="Permalink to “source”">​</a></h5><p><code>GenerationRegion</code></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="featureworld" tabindex="-1">featureWorld() <a class="header-anchor" href="#featureworld" aria-label="Permalink to “featureWorld()”">​</a></h3><blockquote><p><strong>featureWorld</strong>(): <a href="./../../features/#featureworld"><code>FeatureWorld</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L900" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:900</a></p><p>The seam <code>@jsprismarine/features</code> decorates through.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../features/#featureworld"><code>FeatureWorld</code></a></p><hr><h3 id="foreachcenterblock" tabindex="-1">forEachCenterBlock() <a class="header-anchor" href="#foreachcenterblock" aria-label="Permalink to “forEachCenterBlock()”">​</a></h3><blockquote><p><strong>forEachCenterBlock</strong>(<code>visit</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L960" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:960</a></p><p>Every non-air block the center chunk holds, for the translation pass.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="visit" tabindex="-1">visit <a class="header-anchor" href="#visit" aria-label="Permalink to “visit”">​</a></h5><p>(<code>localX</code>, <code>y</code>, <code>localZ</code>, <code>block</code>) =&gt; <code>void</code></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="freezesurfaceheights" tabindex="-1">freezeSurfaceHeights() <a class="header-anchor" href="#freezesurfaceheights" aria-label="Permalink to “freezeSurfaceHeights()”">​</a></h3><blockquote><p><strong>freezeSurfaceHeights</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L876" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:876</a></p><p>Freezes the <code>WORLD_SURFACE_WG</code> heightmap, which Java does once the terrain fill is done.</p><p>The surface pass reads it while writing into the same columns, so taking it live would let a column&#39;s new grass move the surface the next rule reads.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setbiomesections" tabindex="-1">setBiomeSections() <a class="header-anchor" href="#setbiomesections" aria-label="Permalink to “setBiomeSections()”">​</a></h3><blockquote><p><strong>setBiomeSections</strong>(<code>sections</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L511" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:511</a></p><p>Stores the biome IDs computed for this chunk, ready for promotion or transfer.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sections" tabindex="-1">sections <a class="header-anchor" href="#sections" aria-label="Permalink to “sections”">​</a></h5><p><code>PackedBiomeSections</code></p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="spawnentityat" tabindex="-1">spawnEntityAt() <a class="header-anchor" href="#spawnentityat" aria-label="Permalink to “spawnEntityAt()”">​</a></h3><blockquote><p><strong>spawnEntityAt</strong>(<code>type</code>, <code>x</code>, <code>y</code>, <code>z</code>, <code>yaw</code>, <code>options?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L1035" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:1035</a></p><p>Records an entity at the position it stands on, which a structure template saves whole.</p><p>A template&#39;s entities sit between blocks: a cushion is saved at y 0.9375 and a villager in the middle of its block, so the coordinates are taken as given rather than snapped to the block the entity happens to be over.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="type" tabindex="-1">type <a class="header-anchor" href="#type" aria-label="Permalink to “type”">​</a></h5><p><code>string</code></p><h5 id="x-1" tabindex="-1">x <a class="header-anchor" href="#x-1" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-1" tabindex="-1">y <a class="header-anchor" href="#y-1" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-1" tabindex="-1">z <a class="header-anchor" href="#z-1" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="yaw" tabindex="-1">yaw <a class="header-anchor" href="#yaw" aria-label="Permalink to “yaw”">​</a></h5><p><code>number</code></p><h5 id="options-2" tabindex="-1">options? <a class="header-anchor" href="#options-2" aria-label="Permalink to “options?”">​</a></h5><p><code>Omit</code>&lt;<a href="./../../features/#entityspawnoptions"><code>EntitySpawnOptions</code></a>, <code>&quot;yaw&quot;</code>&gt;</p><p>What the spawn carries beyond its yaw: an end crystal&#39;s beam target, its base plate flag and its invulnerability.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="stateat" tabindex="-1">stateAt() <a class="header-anchor" href="#stateat" aria-label="Permalink to “stateAt()”">​</a></h3><blockquote><p><strong>stateAt</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <a href="./../../features/#blockstate"><code>BlockState</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L542" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:542</a></p><p>The state at a block position, air outside the region.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-2" tabindex="-1">x <a class="header-anchor" href="#x-2" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-2" tabindex="-1">y <a class="header-anchor" href="#y-2" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-2" tabindex="-1">z <a class="header-anchor" href="#z-2" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../features/#blockstate"><code>BlockState</code></a></p><hr><h3 id="surfacechunk" tabindex="-1">surfaceChunk() <a class="header-anchor" href="#surfacechunk" aria-label="Permalink to “surfaceChunk()”">​</a></h3><blockquote><p><strong>surfaceChunk</strong>(): <a href="./../../worldgen/#surfacechunk"><code>SurfaceChunk</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L882" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:882</a></p><p>The seam <code>@jsprismarine/worldgen</code>&#39;s surface pass writes through.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../worldgen/#surfacechunk"><code>SurfaceChunk</code></a></p><hr><h3 id="taketrackedpatches" tabindex="-1">takeTrackedPatches() <a class="header-anchor" href="#taketrackedpatches" aria-label="Permalink to “takeTrackedPatches()”">​</a></h3><blockquote><p><strong>takeTrackedPatches</strong>(): readonly <code>RegionChunkPatch</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L690" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:690</a></p><p>Returns the writes grouped by destination chunk, then stops tracking.</p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>RegionChunkPatch</code>[]</p><hr><h3 id="transfer" tabindex="-1">transfer() <a class="header-anchor" href="#transfer" aria-label="Permalink to “transfer()”">​</a></h3><blockquote><p><strong>transfer</strong>(): <code>GenerationRegionTransfer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L407" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:407</a></p><p>Packs the region for <code>postMessage</code> and gives its buffers up.</p><p>The region is spent once this returns, whether or not the caller posts the payload: the buffers are already promised to the other side. What travels is the palette and three flat arrays, which is 18 microseconds for a column against 76 structured-cloned.</p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><code>GenerationRegionTransfer</code></p><p>The payload and the buffers to pass as the transfer list.</p><hr><h3 id="withstructurewrites" tabindex="-1">withStructureWrites() <a class="header-anchor" href="#withstructurewrites" aria-label="Permalink to “withStructureWrites()”">​</a></h3><blockquote><p><strong>withStructureWrites</strong>&lt;<code>T</code>&gt;(<code>place</code>): <code>T</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L679" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:679</a></p><p>Runs a structure piece&#39;s placement, marking what it writes as the structure&#39;s.</p><p>The marks ride along in the patches as RegionChunkPatch.structureBlocks. A later write at the same position by a feature of this pass takes the mark away again, because that feature saw the structure&#39;s block and Java would have let it through too.</p><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to “T”">​</a></h5><p><code>T</code></p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="place" tabindex="-1">place <a class="header-anchor" href="#place" aria-label="Permalink to “place”">​</a></h5><p>() =&gt; <code>T</code></p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>T</code></p><hr><h3 id="workerinput" tabindex="-1">workerInput() <a class="header-anchor" href="#workerinput" aria-label="Permalink to “workerInput()”">​</a></h3><blockquote><p><strong>workerInput</strong>(): <code>GenerationRegionPayload</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L449" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:449</a></p><p>Describes this immutable terrain tile for a worker task without spending its buffers.</p><p><code>GenerationPool</code> structured-clones task input before the worker sees it, so its copies cannot mutate this region. This is for the read-only terrain tiles a feature pass needs; callers that hand a tile away must use <a href="#transfer">GenerationRegion.transfer</a> instead.</p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>GenerationRegionPayload</code></p><p>A payload view whose buffers remain owned by this region.</p><hr><h3 id="write" tabindex="-1">write() <a class="header-anchor" href="#write" aria-label="Permalink to “write()”">​</a></h3><blockquote><p><strong>write</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>state</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L569" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:569</a></p><p>Writes a state, ignoring a position outside the region. Returns whether it landed.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-3" tabindex="-1">x <a class="header-anchor" href="#x-3" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-3" tabindex="-1">y <a class="header-anchor" href="#y-3" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-3" tabindex="-1">z <a class="header-anchor" href="#z-3" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="state" tabindex="-1">state <a class="header-anchor" href="#state" aria-label="Permalink to “state”">​</a></h5><p><a href="./../../features/#blockstate"><code>BlockState</code></a></p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="writebedrock" tabindex="-1">writeBedrock() <a class="header-anchor" href="#writebedrock" aria-label="Permalink to “writeBedrock()”">​</a></h3><blockquote><p><strong>writeBedrock</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>state</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L653" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:653</a></p><p>Writes a block a structure template resolved, which is already a Bedrock state.</p><p>The Java view the region keeps beside it is the Bedrock identifier with no properties. That only decides what a later feature reads back at the position, and the two editions agree on the identifier for every block a vanilla template places; the chunk gets the exact Bedrock state.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-4" tabindex="-1">x <a class="header-anchor" href="#x-4" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-4" tabindex="-1">y <a class="header-anchor" href="#y-4" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-4" tabindex="-1">z <a class="header-anchor" href="#z-4" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="state-1" tabindex="-1">state <a class="header-anchor" href="#state-1" aria-label="Permalink to “state”">​</a></h5><p><a href="./../../structures/#bedrockblockstate"><code>BedrockBlockState</code></a></p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="writename" tabindex="-1">writeName() <a class="header-anchor" href="#writename" aria-label="Permalink to “writeName()”">​</a></h3><blockquote><p><strong>writeName</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>name</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L578" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:578</a></p><p>Writes a name-only state without allocating a <code>BlockState</code> for terrain samples.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-5" tabindex="-1">x <a class="header-anchor" href="#x-5" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-5" tabindex="-1">y <a class="header-anchor" href="#y-5" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-5" tabindex="-1">z <a class="header-anchor" href="#z-5" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="adopt" tabindex="-1">adopt() <a class="header-anchor" href="#adopt" aria-label="Permalink to “adopt()”">​</a></h3><blockquote><p><code>static</code> <strong>adopt</strong>(<code>payload</code>, <code>options</code>): <code>GenerationRegion</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/daa94919d9930bab7665d1faf35d61c7781bc2ef/packages/prismarine/src/world/generators/datadriven/GenerationRegion.ts#L477" target="_blank" rel="noreferrer">prismarine/src/world/generators/datadriven/GenerationRegion.ts:477</a></p><p>Rebuilds a region from a payload that arrived on this thread, without copying a buffer.</p><p>The palette index is rebuilt rather than carried, because it is a <code>Map</code> and a <code>Map</code> is cheaper to rebuild from a few hundred entries than to clone.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="payload" tabindex="-1">payload <a class="header-anchor" href="#payload" aria-label="Permalink to “payload”">​</a></h5><p><code>GenerationRegionPayload</code></p><p>What <a href="#transfer">GenerationRegion.transfer</a> produced.</p><h5 id="options-3" tabindex="-1">options <a class="header-anchor" href="#options-3" aria-label="Permalink to “options”">​</a></h5><p><code>Omit</code>&lt;<a href="./../#generationregionoptions"><code>GenerationRegionOptions</code></a>, <code>&quot;chunkX&quot;</code> | <code>&quot;chunkZ&quot;</code> | <code>&quot;minY&quot;</code> | <code>&quot;height&quot;</code> | <code>&quot;radius&quot;</code>&gt;</p><p>The things that cannot travel: the block oracle, the biome lookup, the sea level, the seed and the template source. The geometry comes from the payload.</p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>GenerationRegion</code></p><p>A region owning the payload&#39;s bytes. The payload is spent.</p>`,283)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};